// ---- shared chrome -------------------------------------------------------
// Inline styles only: Gmail strips <style> blocks. Coral #e35d5d is the brand
// accent from project-overview.md §25.2.
const brand = '#e35d5d';
const site = ($env.AMANTRIKA_SITE_URL || 'https://amantrika.com').replace(/\/+$/, '');
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const inr = (n) => '₹' + Number(n || 0).toLocaleString('en-IN');
const stat = (label, value) => `<div style="display:inline-block;min-width:118px;margin:0 14px 14px 0;"><div style="font-size:26px;font-weight:600;color:#1f1a19;line-height:1.1;">${value}</div><div style="font-size:12px;color:#8a7d7a;text-transform:uppercase;letter-spacing:.06em;margin-top:3px;">${label}</div></div>`;
const shell = (heading, bodyHtml, ctaLabel, ctaHref, footNote) => `
<div style="margin:0;padding:24px 12px;background:#faf7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;">
  <div style="max-width:560px;margin:0 auto;background:#ffffff;border-radius:14px;padding:32px 28px;border:1px solid #f0e6e2;">
    <div style="font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:${brand};font-weight:600;">Amantrika</div>
    <h1 style="margin:14px 0 18px;font-size:22px;line-height:1.32;color:#1f1a19;font-weight:600;">${heading}</h1>
    <div style="font-size:15px;line-height:1.65;color:#453c3a;">${bodyHtml}</div>
    ${ctaHref ? `<div style="margin:26px 0 6px;"><a href="${ctaHref}" style="display:inline-block;background:${brand};color:#ffffff;text-decoration:none;padding:13px 26px;border-radius:9px;font-weight:600;font-size:15px;">${ctaLabel}</a></div>` : ''}
    ${footNote ? `<p style="margin:24px 0 0;font-size:13px;line-height:1.6;color:#8a7d7a;">${footNote}</p>` : ''}
  </div>
  <div style="max-width:560px;margin:16px auto 0;text-align:center;font-size:12px;color:#a29793;">
    Amantrika · digital invitations for Indian celebrations<br/>
    <a href="${site}" style="color:#a29793;">${site.replace(/^https?:\/\//, '')}</a>
  </div>
</div>`;
// No /unsubscribe route exists in the app yet, so RFC 8058's mailto form is
// used. See "Follow-ups" in n8n/README.md.
const unsub = (scope) => 'mailto:' + ($env.AMANTRIKA_UNSUBSCRIBE_MAILBOX || 'unsubscribe@amantrika.com')
  + '?subject=' + encodeURIComponent('unsubscribe ' + scope);
const d = $json;

// Personalised link when the guest has a token, so the reminder lands on their
// own RSVP rather than a generic page.
const url = site + '/invite/' + encodeURIComponent(d.slug)
  + (d.invite_token ? '?t=' + encodeURIComponent(d.invite_token) : '');
const firstName = String(d.guest_name || '').trim().split(/\s+/)[0] || 'there';
const soon = d.kind === 'reminder_1d';
const dateLong = String(d.event_date_long || '').replace(/\s+/g, ' ').trim();

const gcal = 'https://calendar.google.com/calendar/render?action=TEMPLATE'
  + '&text=' + encodeURIComponent(d.title)
  + '&dates=' + d.gcal_start + '/' + d.gcal_end
  + '&details=' + encodeURIComponent(url)
  + (d.city ? '&location=' + encodeURIComponent(d.city) : '');

const ceremonies = (d.ceremonies || []).map((c) => `
  <div style="border-left:2px solid #f0e6e2;padding:0 0 0 14px;margin:0 0 16px;">
    <div style="font-weight:600;color:#1f1a19;font-size:15px;">${esc(c.name)}</div>
    ${c.when ? '<div style="font-size:14px;color:#6b615e;margin-top:2px;">' + esc(c.when) + '</div>' : ''}
    ${c.venue ? '<div style="font-size:14px;color:#453c3a;margin-top:4px;">' + esc(c.venue) + '</div>' : ''}
    ${c.address ? '<div style="font-size:13px;color:#8a7d7a;margin-top:2px;">' + esc(c.address) + '</div>' : ''}
    ${c.dress_code ? '<div style="font-size:13px;color:#8a7d7a;margin-top:4px;">Dress: ' + esc(c.dress_code) + '</div>' : ''}
    ${c.map_url ? '<a href="' + esc(c.map_url) + '" style="display:inline-block;margin-top:7px;font-size:13px;color:' + brand + ';text-decoration:none;">Open in Maps \u2192</a>' : ''}
  </div>`).join('');

const heading = soon ? 'Tomorrow' : 'One week to go';
const bodyHtml = `
  <p style="margin:0 0 18px;">Hi ${esc(firstName)}, ${soon ? '<strong>' + esc(d.title) + '</strong> is tomorrow.' : '<strong>' + esc(d.title) + '</strong> is a week away.'}</p>
  <div style="background:#faf7f5;border-radius:10px;padding:16px 18px;margin:0 0 20px;">
    <div style="font-weight:600;color:#1f1a19;">${esc(dateLong)}</div>
    ${d.event_time ? '<div style="font-size:14px;color:#6b615e;margin-top:3px;">' + esc(d.event_time) + '</div>' : ''}
    ${d.city ? '<div style="font-size:14px;color:#6b615e;margin-top:3px;">' + esc(d.city) + '</div>' : ''}
    <a href="${gcal}" style="display:inline-block;margin-top:11px;font-size:13px;color:${brand};text-decoration:none;">Add to calendar \u2192</a>
  </div>
  ${ceremonies ? '<div style="margin:0 0 10px;font-weight:600;color:#1f1a19;">Your schedule</div>' + ceremonies : ''}
  <p style="margin:0;font-size:14px;color:#6b615e;">You are down as attending${Number(d.headcount) > 1 ? ' with ' + (Number(d.headcount) - 1) + ' other(s)' : ''}. If anything has changed, you can update your answer on the invitation.</p>`;

return { json: {
  dedupe_key: d.dedupe_key,
  to: d.guest_email,
  stored: {
    // The address is never stored — only automation.hash_email() of it, written
    // by the claim node into recipient_hash.
    guest_id: d.guest_id, event_id: d.event_id, slug: d.slug, title: d.title,
    kind: d.kind, headcount: d.headcount, dedupe_key: d.dedupe_key,
    subject: soon ? d.title + ' is tomorrow' : d.title + ' \u2014 one week to go',
    html: shell(heading, bodyHtml, 'Open the invitation', url,
      `You are receiving this because you RSVP\u2019d to this celebration. <a href="${unsub('reminder')}" style="color:#8a7d7a;">Unsubscribe</a>`),
    text: heading + '\n\n' + d.title + '\n' + dateLong + (d.event_time ? ' \u00b7 ' + d.event_time : '')
      + (d.city ? '\n' + d.city : '') + '\n\n' + url,
    unsubscribe: unsub('reminder'),
  },
} };

parameters.jsonBody:
={{ JSON.stringify({
  from: $env.AMANTRIKA_EMAIL_FROM,
  to: [ $json.recipient ],
  subject: $json.payload.subject,
  html: $json.payload.html,
  text: $json.payload.text,
  headers: $json.payload.unsubscribe
    ? { 'List-Unsubscribe': '<' + $json.payload.unsubscribe + '>',
        'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' }
    : {}
}) }}
